create table if not exists public.srk_booking_refund_requests (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.service_bookings(id) on delete restrict,
  customer_user_id uuid not null references auth.users(id) on delete restrict,
  amount numeric(12,2) not null check (amount > 0 and amount <= 10000000),
  reason text not null check (length(btrim(reason)) between 20 and 1000),
  status text not null default 'requested'
    check (status in ('requested','in_review','approved','rejected','processing','unknown','processed')),
  admin_note text check (admin_note is null or length(admin_note) <= 2000),
  refund_record_id uuid unique references public.srk_razorpay_refunds(id) on delete restrict,
  decided_by uuid references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  processed_at timestamptz
);

create index if not exists srk_booking_refund_requests_status_created_idx
  on public.srk_booking_refund_requests(status, created_at desc);

alter table public.srk_booking_refund_requests enable row level security;
revoke all on public.srk_booking_refund_requests from public, anon, authenticated;
grant select, insert, update, delete on public.srk_booking_refund_requests to service_role;

create or replace function public.srk_customer_create_booking_refund_request(
  p_booking_id uuid,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_uid uuid := auth.uid();
  v_booking public.service_bookings%rowtype;
  v_request public.srk_booking_refund_requests%rowtype;
begin
  if v_uid is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='28000'; end if;
  if p_booking_id is null or p_reason is null
     or length(btrim(p_reason)) not between 20 and 1000 then
    raise exception 'REFUND_REASON_MUST_BE_20_TO_1000_CHARACTERS' using errcode='22023';
  end if;

  select * into v_booking from public.service_bookings
  where id=p_booking_id and customer_user_id=v_uid
  for update;
  if not found then raise exception 'BOOKING_NOT_FOUND_OR_NOT_OWNED' using errcode='42501'; end if;
  if v_booking.payment_status <> 'paid' or v_booking.payment_verified_at is null
     or coalesce(v_booking.amount_paid,0) <= 0 then
    raise exception 'ONLY_VERIFIED_PAID_BOOKINGS_CAN_REQUEST_REFUND' using errcode='55000';
  end if;
  if exists(select 1 from public.srk_razorpay_refunds r where r.booking_id=p_booking_id and r.status in ('requested','processing','unknown','processed')) then
    raise exception 'REFUND_ALREADY_EXISTS_FOR_BOOKING' using errcode='23505';
  end if;
  if exists(select 1 from public.srk_manual_refund_entries r where r.booking_id=p_booking_id) then
    raise exception 'REFUND_ALREADY_RECORDED_FOR_BOOKING' using errcode='23505';
  end if;

  select * into v_request from public.srk_booking_refund_requests
  where booking_id=p_booking_id for update;
  if found then
    if v_request.status in ('rejected') then
      update public.srk_booking_refund_requests
      set customer_user_id=v_uid, amount=round(v_booking.amount_paid,2),
          reason=btrim(p_reason),status='requested',admin_note=null,
          refund_record_id=null,decided_by=null,processed_at=null,updated_at=clock_timestamp()
      where id=v_request.id returning * into v_request;
    else
      raise exception 'REFUND_REQUEST_ALREADY_SUBMITTED' using errcode='23505';
    end if;
  else
    insert into public.srk_booking_refund_requests(booking_id,customer_user_id,amount,reason)
    values(p_booking_id,v_uid,round(v_booking.amount_paid,2),btrim(p_reason))
    returning * into v_request;
  end if;

  return jsonb_build_object('success',true,'request_id',v_request.id,'amount',v_request.amount,'status',v_request.status);
end
$function$;

create or replace function public.srk_customer_list_booking_refund_requests()
returns table(
  id uuid, booking_id uuid, amount numeric, reason text, status text,
  admin_note text, created_at timestamptz, updated_at timestamptz, processed_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='28000'; end if;
  return query
  select r.id,r.booking_id,r.amount,r.reason,r.status,r.admin_note,r.created_at,r.updated_at,r.processed_at
  from public.srk_booking_refund_requests r
  where r.customer_user_id=auth.uid()
  order by r.created_at desc;
end
$function$;

create or replace function public.srk_admin_list_booking_refund_requests(p_limit integer default 200)
returns table(
  id uuid, booking_id uuid, customer_user_id uuid, customer_name text, customer_phone text,
  amount numeric, reason text, status text, admin_note text, created_at timestamptz,
  updated_at timestamptz, payment_status text, payment_method text,
  razorpay_payment_id text, has_manual_payment boolean, refund_record_id uuid,
  refund_id text, provider_status text
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if auth.uid() is null or not public.is_srk_admin() then
    raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';
  end if;
  return query
  select r.id,r.booking_id,r.customer_user_id,b.customer_name,b.phone,
    r.amount,r.reason,r.status,r.admin_note,r.created_at,r.updated_at,
    b.payment_status,b.payment_method,b.razorpay_payment_id,
    exists(select 1 from public.srk_manual_payment_entries m where m.booking_id=b.id),
    r.refund_record_id,rr.refund_id,rr.provider_status
  from public.srk_booking_refund_requests r
  join public.service_bookings b on b.id=r.booking_id
  left join public.srk_razorpay_refunds rr on rr.id=r.refund_record_id
  order by r.created_at desc
  limit greatest(1,least(coalesce(p_limit,200),300));
end
$function$;

create or replace function public.srk_admin_decide_booking_refund_request(
  p_request_id uuid,
  p_status text,
  p_admin_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_request public.srk_booking_refund_requests%rowtype;
begin
  if auth.uid() is null or not public.is_srk_admin() then
    raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';
  end if;
  if p_request_id is null or p_status not in ('in_review','approved','rejected')
     or (p_admin_note is not null and length(p_admin_note)>2000) then
    raise exception 'INVALID_REFUND_REQUEST_DECISION' using errcode='22023';
  end if;
  select * into v_request from public.srk_booking_refund_requests
  where id=p_request_id for update;
  if not found then raise exception 'REFUND_REQUEST_NOT_FOUND'; end if;
  if v_request.status in ('processing','unknown','processed') then
    raise exception 'REFUND_ALREADY_BEING_PROCESSED_OR_COMPLETED' using errcode='55000';
  end if;
  if v_request.status='rejected' and p_status<>'in_review' then
    raise exception 'REJECTED_REQUEST_MUST_BE_REOPENED_FOR_REVIEW_FIRST' using errcode='55000';
  end if;
  update public.srk_booking_refund_requests
  set status=p_status,admin_note=nullif(btrim(coalesce(p_admin_note,'')), ''),
      decided_by=auth.uid(),updated_at=clock_timestamp()
  where id=p_request_id returning * into v_request;
  return jsonb_build_object('success',true,'request_id',v_request.id,'status',v_request.status);
end
$function$;

create or replace function public.srk_admin_prepare_booking_refund(
  p_request_id uuid
)
returns table(
  refund_record_id uuid, booking_id uuid, payment_id text, amount_paise bigint,
  idempotency_key text, status text
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_request public.srk_booking_refund_requests%rowtype;
  v_booking public.service_bookings%rowtype;
  v_refund public.srk_razorpay_refunds%rowtype;
  v_payout public.srk_electrician_payouts%rowtype;
  v_amount numeric(12,2);
begin
  if auth.uid() is null or not public.is_srk_admin() then
    raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';
  end if;
  select * into v_request from public.srk_booking_refund_requests
  where id=p_request_id for update;
  if not found then raise exception 'REFUND_REQUEST_NOT_FOUND'; end if;
  if v_request.status not in ('approved','processing','unknown') then
    raise exception 'REFUND_REQUEST_MUST_BE_APPROVED_FIRST' using errcode='55000';
  end if;
  select * into v_booking from public.service_bookings where id=v_request.booking_id for update;
  if not found then raise exception 'BOOKING_NOT_FOUND'; end if;
  if v_booking.payment_status<>'paid' or v_booking.payment_verified_at is null
     or v_booking.razorpay_payment_id is null or v_booking.razorpay_payment_id !~ '^pay_[A-Za-z0-9]+$'
     or coalesce(v_booking.amount_paid,0)<=0 then
    raise exception 'VERIFIED_RAZORPAY_PAYMENT_REQUIRED' using errcode='55000';
  end if;
  v_amount:=round(v_booking.amount_paid,2);
  if v_amount<>v_request.amount then raise exception 'REFUND_AMOUNT_CHANGED_SINCE_REQUEST' using errcode='55000'; end if;
  if v_booking.quote_status<>'approved' then
    raise exception 'TIMER_OR_NON_QUOTE_REFUND_REQUIRES_SEPARATE_PAYMENT_RECONCILIATION' using errcode='55000';
  end if;
  if v_booking.quoted_amount is null or v_booking.service_charge is null or v_booking.materials_amount is null
     or v_amount<>round(v_booking.quoted_amount,2)
     or v_amount<>round(v_booking.service_charge+v_booking.materials_amount,2) then
    raise exception 'PAID_AMOUNT_DOES_NOT_MATCH_APPROVED_QUOTE' using errcode='55000';
  end if;
  select * into v_refund from public.srk_razorpay_refunds where booking_id=v_booking.id for update;
  if found then
    if v_refund.status='failed' then raise exception 'PREVIOUS_REFUND_FAILED_RECONCILE_FIRST'; end if;
    update public.srk_booking_refund_requests
    set status=case when v_refund.status='processed' then 'processed' else 'processing' end,
        refund_record_id=v_refund.id,updated_at=clock_timestamp(),
        processed_at=case when v_refund.status='processed' then coalesce(v_refund.processed_at,clock_timestamp()) else null end
    where id=v_request.id;
    return query select v_refund.id,v_refund.booking_id,v_refund.payment_id,v_refund.amount_paise,v_refund.idempotency_key,v_refund.status;
    return;
  end if;
  select * into v_payout from public.srk_electrician_payouts where booking_id=v_booking.id for update;
  if found then
    if v_payout.payout_status='paid' then raise exception 'ELECTRICIAN_PAYOUT_ALREADY_PAID_RECONCILIATION_REQUIRED'; end if;
    if v_payout.payout_status not in ('pending','blocked') then raise exception 'ELECTRICIAN_PAYOUT_STATE_REQUIRES_RECONCILIATION'; end if;
    update public.srk_electrician_payouts set payout_status='blocked',
      payout_note='Customer refund in progress',updated_at=clock_timestamp() where id=v_payout.id;
  end if;
  insert into public.srk_razorpay_refunds(
    booking_id,payment_id,amount,amount_paise,idempotency_key,status,reason,admin_user_id,previous_payout_note
  ) values (
    v_booking.id,v_booking.razorpay_payment_id,v_amount,round(v_amount*100)::bigint,
    replace(gen_random_uuid()::text,'-',''),'requested',
    left('Customer refund request: '||v_request.reason,250),auth.uid(),
    case when found then v_payout.payout_note else null end
  ) returning * into v_refund;
  update public.srk_booking_refund_requests
  set status='processing',refund_record_id=v_refund.id,decided_by=auth.uid(),updated_at=clock_timestamp()
  where id=v_request.id;
  return query select v_refund.id,v_refund.booking_id,v_refund.payment_id,v_refund.amount_paise,v_refund.idempotency_key,v_refund.status;
end
$function$;

create or replace function public.srk_service_reconcile_booking_refund(
  p_refund_record_id uuid,
  p_provider_refund_id text,
  p_provider_status text,
  p_error text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_refund public.srk_razorpay_refunds%rowtype;
  v_status text;
begin
  if auth.role() <> 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_refund_record_id is null or p_provider_status not in ('pending','processed','failed')
     or (p_provider_refund_id is not null and p_provider_refund_id !~ '^rfnd_[A-Za-z0-9]+$') then
    raise exception 'INVALID_PROVIDER_REFUND_RESULT' using errcode='22023';
  end if;
  select * into v_refund from public.srk_razorpay_refunds
  where id=p_refund_record_id for update;
  if not found then raise exception 'REFUND_RECORD_NOT_FOUND'; end if;
  if v_refund.status='processed' then
    return jsonb_build_object('success',true,'status','processed','replayed',true);
  end if;
  v_status:=case p_provider_status when 'pending' then 'processing' when 'processed' then 'processed' else 'failed' end;
  update public.srk_razorpay_refunds
  set refund_id=coalesce(p_provider_refund_id,refund_id),
      provider_status=p_provider_status,status=v_status,
      last_error=case when p_provider_status='failed' then left(coalesce(p_error,'Refund failed'),500) else null end,
      processed_at=case when p_provider_status='processed' then clock_timestamp() else null end,
      updated_at=clock_timestamp()
  where id=p_refund_record_id;
  update public.srk_booking_refund_requests
  set status=case when p_provider_status='processed' then 'processed'
                  when p_provider_status='failed' then 'unknown' else 'processing' end,
      updated_at=clock_timestamp(),
      processed_at=case when p_provider_status='processed' then clock_timestamp() else null end
  where refund_record_id=p_refund_record_id;
  if p_provider_status='processed' then
    update public.service_bookings set payment_status='refunded'
    where id=v_refund.booking_id and payment_status='paid';
  end if;
  return jsonb_build_object('success',true,'status',v_status,'booking_id',v_refund.booking_id);
end
$function$;

create or replace function public.srk_admin_finalize_manual_booking_refund(
  p_request_id uuid,
  p_reference text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_request public.srk_booking_refund_requests%rowtype;
  v_result jsonb;
begin
  if auth.uid() is null or not public.is_srk_admin() then
    raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';
  end if;
  select * into v_request from public.srk_booking_refund_requests
  where id=p_request_id for update;
  if not found then raise exception 'REFUND_REQUEST_NOT_FOUND'; end if;
  if v_request.status<>'approved' then raise exception 'REFUND_REQUEST_MUST_BE_APPROVED_FIRST'; end if;
  v_result:=public.srk_admin_record_manual_refund(v_request.booking_id,p_reference,p_note);
  update public.srk_booking_refund_requests set status='processed',
    admin_note=coalesce(nullif(btrim(coalesce(p_note,'')),''),admin_note),
    decided_by=auth.uid(),processed_at=clock_timestamp(),updated_at=clock_timestamp()
  where id=p_request_id;
  return v_result||jsonb_build_object('request_id',p_request_id,'status','processed');
end
$function$;

revoke all on function public.srk_customer_create_booking_refund_request(uuid,text) from public,anon;
revoke all on function public.srk_customer_list_booking_refund_requests() from public,anon;
revoke all on function public.srk_admin_list_booking_refund_requests(integer) from public,anon;
revoke all on function public.srk_admin_decide_booking_refund_request(uuid,text,text) from public,anon;
revoke all on function public.srk_admin_prepare_booking_refund(uuid) from public,anon;
revoke all on function public.srk_service_reconcile_booking_refund(uuid,text,text,text) from public,anon,authenticated;
revoke all on function public.srk_admin_finalize_manual_booking_refund(uuid,text,text) from public,anon;
grant execute on function public.srk_customer_create_booking_refund_request(uuid,text) to authenticated;
grant execute on function public.srk_customer_list_booking_refund_requests() to authenticated;
grant execute on function public.srk_admin_list_booking_refund_requests(integer) to authenticated;
grant execute on function public.srk_admin_decide_booking_refund_request(uuid,text,text) to authenticated;
grant execute on function public.srk_admin_prepare_booking_refund(uuid) to authenticated;
grant execute on function public.srk_admin_finalize_manual_booking_refund(uuid,text,text) to authenticated;
grant execute on function public.srk_service_reconcile_booking_refund(uuid,text,text,text) to service_role;

commit;

-- Safe correction of an already-settled electrician payout reference.
-- This does not create, reverse, or alter the financial settlement itself.
-- It only replaces a previously mistyped reference after an Admin verifies the actual transfer.

CREATE OR REPLACE FUNCTION public.srk_capture_admin_audit_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_old jsonb := CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  v_new jsonb := CASE WHEN TG_OP='DELETE' THEN '{}'::jsonb ELSE to_jsonb(NEW) END;
  v_before jsonb := '{}'::jsonb;
  v_after jsonb := '{}'::jsonb;
  v_fields text[] := ARRAY[]::text[];
  v_key text;
  v_entity_type text;
  v_entity_id uuid;
  v_booking_id uuid;
  v_actor uuid := auth.uid();
  v_role text;
  v_allow text[];
BEGIN
  v_entity_type := CASE TG_TABLE_NAME
    WHEN 'service_bookings' THEN 'booking'
    WHEN 'electrician_profiles' THEN 'electrician_profile'
    WHEN 'electrician_applications' THEN 'electrician_application'
    WHEN 'srk_manual_payment_entries' THEN 'manual_payment'
    WHEN 'srk_manual_refund_entries' THEN 'manual_refund'
    WHEN 'srk_electrician_payouts' THEN 'electrician_payout'
    ELSE NULL END;
  IF v_entity_type IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_allow := CASE v_entity_type
    WHEN 'booking' THEN ARRAY['status','payment_status','payment_method','amount_paid','quoted_amount','quote_status','service_charge','materials_amount','assigned_electrician_id','commission_amount']
    WHEN 'electrician_profile' THEN ARRAY['active','verification_status','auth_user_id','user_id']
    WHEN 'electrician_application' THEN ARRAY['verification_status','active']
    WHEN 'manual_payment' THEN ARRAY['booking_id','payment_method','amount']
    WHEN 'manual_refund' THEN ARRAY['booking_id','payment_entry_id','amount']
    WHEN 'electrician_payout' THEN ARRAY['booking_id','payout_status','payout_method','payout_reference','payout_note','electrician_payable','platform_commission','paid_at']
    ELSE ARRAY[]::text[] END;

  v_entity_id := coalesce(nullif(v_new->>'id','')::uuid,nullif(v_old->>'id','')::uuid);
  v_booking_id := CASE WHEN v_entity_type='booking' THEN v_entity_id
    ELSE coalesce(nullif(v_new->>'booking_id','')::uuid,nullif(v_old->>'booking_id','')::uuid) END;
  IF v_entity_id IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  FOREACH v_key IN ARRAY v_allow LOOP
    IF v_old->v_key IS DISTINCT FROM v_new->v_key THEN
      v_fields := array_append(v_fields,v_key);
      IF v_old ? v_key THEN v_before := v_before || jsonb_build_object(v_key,v_old->v_key); END IF;
      IF v_new ? v_key THEN v_after := v_after || jsonb_build_object(v_key,v_new->v_key); END IF;
    END IF;
  END LOOP;
  IF cardinality(v_fields)=0 THEN
    IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_role := CASE WHEN v_actor IS NULL THEN 'system'
    WHEN public.is_srk_admin() THEN 'admin' ELSE 'user' END;
  INSERT INTO public.srk_admin_audit_events
    (entity_type,entity_id,booking_id,action,actor_user_id,actor_role,changed_fields,before_data,after_data)
  VALUES
    (v_entity_type,v_entity_id,v_booking_id,
     CASE TG_OP WHEN 'INSERT' THEN 'created' WHEN 'UPDATE' THEN 'updated' ELSE 'deleted' END,
     v_actor,v_role,v_fields,v_before,v_after);
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_correct_electrician_payout_reference(
  p_payout_id uuid,
  p_expected_reference text,
  p_new_reference text,
  p_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_booking_id uuid;
  v_row public.srk_electrician_payouts%ROWTYPE;
  v_new_reference text := pg_catalog.btrim(coalesce(p_new_reference, ''));
  v_note text := nullif(pg_catalog.btrim(p_note), '');
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_srk_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING errcode = '42501';
  END IF;
  IF p_payout_id IS NULL THEN
    RAISE EXCEPTION 'Payout ID is required';
  END IF;
  IF p_expected_reference IS NULL OR pg_catalog.length(pg_catalog.btrim(p_expected_reference)) < 4 THEN
    RAISE EXCEPTION 'Expected existing reference is required';
  END IF;
  IF v_new_reference !~ '^[A-Za-z0-9]{8,40}$' THEN
    RAISE EXCEPTION 'Enter a valid UTR / UPI transaction reference (8-40 letters or digits)';
  END IF;
  IF v_note IS NULL OR pg_catalog.length(v_note) < 8 OR pg_catalog.length(v_note) > 500 THEN
    RAISE EXCEPTION 'Correction note must contain 8-500 characters';
  END IF;

  -- Match the settlement RPC lock order: booking first, then payout.
  SELECT booking_id INTO v_booking_id
    FROM public.srk_electrician_payouts
   WHERE id = p_payout_id;
  IF NOT FOUND OR v_booking_id IS NULL THEN
    RAISE EXCEPTION 'Payout record not found or has no booking';
  END IF;

  PERFORM 1 FROM public.service_bookings WHERE id = v_booking_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payout booking not found';
  END IF;

  SELECT * INTO v_row
    FROM public.srk_electrician_payouts
   WHERE id = p_payout_id
   FOR UPDATE;
  IF NOT FOUND OR v_row.booking_id IS DISTINCT FROM v_booking_id THEN
    RAISE EXCEPTION 'Payout record changed; retry the operation';
  END IF;
  IF v_row.payout_status <> 'paid' THEN
    RAISE EXCEPTION 'Only an already-paid payout reference can be corrected';
  END IF;
  IF v_row.payout_reference IS DISTINCT FROM pg_catalog.btrim(p_expected_reference) THEN
    RAISE EXCEPTION 'Existing reference changed; refresh and verify before retrying';
  END IF;
  IF v_row.payout_reference = v_new_reference THEN
    RAISE EXCEPTION 'New reference is the same as the existing reference';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.srk_electrician_payouts p
     WHERE p.id <> p_payout_id AND p.payout_reference = v_new_reference
  ) THEN
    RAISE EXCEPTION 'This transaction reference is already used by another payout';
  END IF;

  UPDATE public.srk_electrician_payouts
     SET payout_reference = v_new_reference,
         payout_note = concat_ws(E'\n', nullif(v_row.payout_note, ''), v_note),
         updated_at = pg_catalog.now()
   WHERE id = p_payout_id;

  RETURN pg_catalog.jsonb_build_object(
    'success', true,
    'payout_id', p_payout_id,
    'status', 'paid',
    'reference_corrected', true
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.srk_admin_correct_electrician_payout_reference(uuid,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.srk_admin_correct_electrician_payout_reference(uuid,text,text,text) TO authenticated;

-- SRK ELECTRONIC 14.1.10: customer-controlled work start, server-side timer,
-- completion approval and admin resolution of work-completion disputes.
-- Existing approved quote amounts remain fixed; timer records duration only.
ALTER TABLE public.service_bookings
  ADD COLUMN IF NOT EXISTS work_start_approval_status text NOT NULL DEFAULT 'not_requested',
  ADD COLUMN IF NOT EXISTS work_start_requested_at timestamptz,
  ADD COLUMN IF NOT EXISTS work_timer_running boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS work_timer_seconds integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS completion_requested_at timestamptz,
  ADD COLUMN IF NOT EXISTS completion_approval_status text NOT NULL DEFAULT 'not_requested',
  ADD COLUMN IF NOT EXISTS customer_completed_at timestamptz;

ALTER TABLE public.service_bookings
  DROP CONSTRAINT IF EXISTS service_bookings_status_check;
ALTER TABLE public.service_bookings
  ADD CONSTRAINT service_bookings_status_check CHECK (
    status = ANY (ARRAY[
      'new','confirmed','assigned','inspection','awaiting_quote_approval',
      'quote_approved','awaiting_work_start_approval','quote_rejected',
      'in_progress','completed','cancelled'
    ])
  );

ALTER TABLE public.service_bookings
  DROP CONSTRAINT IF EXISTS service_bookings_assignment_status_requires_electrician;
ALTER TABLE public.service_bookings
  ADD CONSTRAINT service_bookings_assignment_status_requires_electrician CHECK (
    status <> ALL (ARRAY['assigned','inspection','awaiting_quote_approval','quote_approved',
      'awaiting_work_start_approval','quote_rejected','in_progress','completed'])
    OR assigned_electrician_id IS NOT NULL
  );

ALTER TABLE public.service_bookings
  ADD CONSTRAINT service_bookings_work_start_approval_check
    CHECK (work_start_approval_status IN ('not_requested','pending','approved','rejected')),
  ADD CONSTRAINT service_bookings_completion_approval_check
    CHECK (completion_approval_status IN ('not_requested','pending','approved','rejected','disputed','admin_approved','reopened')),
  ADD CONSTRAINT service_bookings_work_timer_seconds_check
    CHECK (work_timer_seconds BETWEEN 0 AND 604800);

CREATE OR REPLACE FUNCTION public.srk_electrician_request_work_start(p_booking_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
DECLARE v_profile_id uuid; v_booking public.service_bookings%rowtype;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT id INTO v_profile_id FROM public.electrician_profiles
   WHERE (user_id=auth.uid() OR auth_user_id=auth.uid())
     AND verification_status='approved' AND active=true
   ORDER BY created_at DESC LIMIT 1;
  IF v_profile_id IS NULL THEN RAISE EXCEPTION 'Approved active electrician required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_booking FROM public.service_bookings
   WHERE id=p_booking_id AND assigned_electrician_id=v_profile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Assigned booking not found' USING ERRCODE='42501'; END IF;
  IF v_booking.status<>'quote_approved' OR v_booking.quote_status<>'approved' THEN
    RAISE EXCEPTION 'Customer-approved quote is required before requesting work start';
  END IF;
  IF v_booking.work_start_approval_status NOT IN ('not_requested','rejected') THEN
    RAISE EXCEPTION 'Work start approval is already pending or granted';
  END IF;
  UPDATE public.service_bookings SET
    status='awaiting_work_start_approval',
    work_start_approval_status='pending',
    work_start_requested_at=pg_catalog.now(),
    work_timer_running=false
  WHERE id=p_booking_id;
  RETURN pg_catalog.jsonb_build_object('success',true,'status','awaiting_work_start_approval');
END;
$function$;

CREATE OR REPLACE FUNCTION public.srk_customer_respond_work_start(p_booking_id uuid,p_response text)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
DECLARE v_booking public.service_bookings%rowtype;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF p_response IS NULL OR p_response NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Invalid response'; END IF;
  SELECT * INTO v_booking FROM public.service_bookings
   WHERE id=p_booking_id AND customer_user_id=auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer booking not found' USING ERRCODE='42501'; END IF;
  IF v_booking.status<>'awaiting_work_start_approval' OR v_booking.work_start_approval_status<>'pending' THEN
    RAISE EXCEPTION 'No work-start request is waiting for approval';
  END IF;
  IF p_response='approved' THEN
    INSERT INTO srk_private.work_transition_authorizations(transaction_id,booking_id,target_status)
    VALUES (pg_catalog.txid_current(),p_booking_id,'in_progress');
  END IF;
  UPDATE public.service_bookings SET
    work_start_approval_status=p_response,
    status=CASE WHEN p_response='approved' THEN 'in_progress' ELSE 'quote_approved' END,
    work_started_at=CASE WHEN p_response='approved' THEN pg_catalog.now() ELSE NULL END,
    work_timer_running=(p_response='approved'),
    work_timer_seconds=0
  WHERE id=p_booking_id;
  IF p_response='approved' THEN
    DELETE FROM srk_private.work_transition_authorizations
     WHERE transaction_id=pg_catalog.txid_current() AND booking_id=p_booking_id AND target_status='in_progress';
  END IF;
  RETURN pg_catalog.jsonb_build_object('success',true,'response',p_response);
END;
$function$;

CREATE OR REPLACE FUNCTION public.srk_electrician_request_work_completion(p_booking_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
DECLARE v_profile_id uuid; v_booking public.service_bookings%rowtype; v_seconds integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  SELECT id INTO v_profile_id FROM public.electrician_profiles
   WHERE (user_id=auth.uid() OR auth_user_id=auth.uid())
     AND verification_status='approved' AND active=true
   ORDER BY created_at DESC LIMIT 1;
  IF v_profile_id IS NULL THEN RAISE EXCEPTION 'Approved active electrician required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_booking FROM public.service_bookings
   WHERE id=p_booking_id AND assigned_electrician_id=v_profile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Assigned booking not found' USING ERRCODE='42501'; END IF;
  IF v_booking.status<>'in_progress' OR NOT v_booking.work_timer_running OR v_booking.work_started_at IS NULL THEN
    RAISE EXCEPTION 'No running work timer exists';
  END IF;
  v_seconds:=LEAST(604800,v_booking.work_timer_seconds+
    GREATEST(0,FLOOR(EXTRACT(EPOCH FROM (pg_catalog.now()-v_booking.work_started_at)))::integer));
  UPDATE public.service_bookings SET
    work_timer_seconds=v_seconds,
    work_timer_running=false,
    completion_requested_at=pg_catalog.now(),
    completion_approval_status='pending'
  WHERE id=p_booking_id;
  RETURN pg_catalog.jsonb_build_object('success',true,'completion_status','pending','work_seconds',v_seconds);
END;
$function$;

CREATE OR REPLACE FUNCTION public.srk_customer_respond_work_completion(p_booking_id uuid,p_response text,p_note text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
DECLARE v_booking public.service_bookings%rowtype; v_note text:=NULLIF(pg_catalog.btrim(p_note),'');
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF p_response IS NULL OR p_response NOT IN ('approved','rejected','disputed') OR (p_note IS NOT NULL AND pg_catalog.length(p_note)>1000) THEN
    RAISE EXCEPTION 'Invalid completion response';
  END IF;
  IF p_response='disputed' AND (v_note IS NULL OR pg_catalog.length(v_note)<20) THEN
    RAISE EXCEPTION 'विवाद का कारण कम से कम 20 अक्षरों में लिखें';
  END IF;
  SELECT * INTO v_booking FROM public.service_bookings
   WHERE id=p_booking_id AND customer_user_id=auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer booking not found' USING ERRCODE='42501'; END IF;
  IF v_booking.status<>'in_progress' OR v_booking.completion_approval_status<>'pending'
     OR v_booking.completion_requested_at IS NULL THEN
    RAISE EXCEPTION 'No completion request is waiting for your response';
  END IF;
  IF p_response='approved' THEN
    INSERT INTO srk_private.work_transition_authorizations(transaction_id,booking_id,target_status)
    VALUES (pg_catalog.txid_current(),p_booking_id,'completed');
    UPDATE public.service_bookings SET status='completed',
      completion_approval_status='approved',customer_completed_at=pg_catalog.now(),
      work_timer_running=false
    WHERE id=p_booking_id;
  ELSIF p_response='rejected' THEN
    UPDATE public.service_bookings SET completion_approval_status='rejected',
      completion_requested_at=NULL,work_started_at=pg_catalog.now(),
      work_timer_running=true
    WHERE id=p_booking_id;
  ELSE
    INSERT INTO public.srk_booking_complaints
      (booking_id,customer_user_id,category,description)
    VALUES (p_booking_id,auth.uid(),'service_quality','काम पूरा होने पर विवाद: '||v_note);
    UPDATE public.service_bookings SET completion_approval_status='disputed',
      work_timer_running=false
    WHERE id=p_booking_id;
  END IF;
  IF p_response='approved' THEN
    DELETE FROM srk_private.work_transition_authorizations
     WHERE transaction_id=pg_catalog.txid_current() AND booking_id=p_booking_id AND target_status='completed';
  END IF;
  RETURN pg_catalog.jsonb_build_object('success',true,'response',p_response);
END;
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_resolve_work_dispute(
  p_booking_id uuid,p_resolution text,p_admin_note text
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
DECLARE v_booking public.service_bookings%rowtype; v_admin_id uuid:=auth.uid(); v_complaint public.srk_booking_complaints%rowtype;
BEGIN
  IF v_admin_id IS NULL OR NOT public.is_srk_admin() THEN
    RAISE EXCEPTION 'Admin permission required' USING ERRCODE='42501';
  END IF;
  IF p_resolution IS NULL OR p_resolution NOT IN ('approve_completion','reopen_work')
     OR p_admin_note IS NULL OR pg_catalog.length(pg_catalog.btrim(p_admin_note))<10
     OR pg_catalog.length(p_admin_note)>2000 THEN RAISE EXCEPTION 'Valid resolution and admin note required'; END IF;
  SELECT * INTO v_booking FROM public.service_bookings WHERE id=p_booking_id FOR UPDATE;
  IF NOT FOUND OR v_booking.completion_approval_status<>'disputed' THEN
    RAISE EXCEPTION 'No disputed completion exists for this booking';
  END IF;
  SELECT * INTO v_complaint FROM public.srk_booking_complaints
   WHERE booking_id=p_booking_id AND category='service_quality'
     AND description LIKE 'काम पूरा होने पर विवाद:%'
     AND status IN ('new','in_review')
   ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Open work-completion dispute record not found'; END IF;
  IF p_resolution='approve_completion' THEN
    INSERT INTO srk_private.work_transition_authorizations(transaction_id,booking_id,target_status)
    VALUES (pg_catalog.txid_current(),p_booking_id,'completed');
    UPDATE public.service_bookings SET status='completed',
      completion_approval_status='admin_approved',customer_completed_at=pg_catalog.now(),
      work_timer_running=false
    WHERE id=p_booking_id;
  ELSE
    INSERT INTO srk_private.work_transition_authorizations(transaction_id,booking_id,target_status)
    VALUES (pg_catalog.txid_current(),p_booking_id,'in_progress');
    UPDATE public.service_bookings SET status='in_progress',
      completion_approval_status='reopened',completion_requested_at=NULL,
      work_started_at=pg_catalog.now(),work_timer_running=true
    WHERE id=p_booking_id;
  END IF;
  IF p_resolution='approve_completion' THEN
    DELETE FROM srk_private.work_transition_authorizations
     WHERE transaction_id=pg_catalog.txid_current() AND booking_id=p_booking_id AND target_status='completed';
  ELSE
    DELETE FROM srk_private.work_transition_authorizations
     WHERE transaction_id=pg_catalog.txid_current() AND booking_id=p_booking_id AND target_status='in_progress';
  END IF;
  UPDATE public.srk_booking_complaints SET status='resolved',admin_note=p_admin_note,
    updated_at=pg_catalog.now(),updated_by=v_admin_id,resolved_at=pg_catalog.now(),resolved_by=v_admin_id
  WHERE id=v_complaint.id;
  INSERT INTO public.srk_booking_complaint_events
    (complaint_id,actor_user_id,actor_role,from_status,to_status,note)
  VALUES (v_complaint.id,v_admin_id,'admin',v_complaint.status,'resolved',p_admin_note);
  RETURN pg_catalog.jsonb_build_object('success',true,'resolution',p_resolution);
END;
$function$;

CREATE OR REPLACE FUNCTION public.srk_update_booking_work_status(p_booking_id uuid,p_status text)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
DECLARE v_profile_id uuid; v_booking public.service_bookings%rowtype;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
  IF p_status<>'inspection' THEN RAISE EXCEPTION 'काम शुरू और पूरा करने के लिए ग्राहक की मंजूरी जरूरी है'; END IF;
  SELECT id INTO v_profile_id FROM public.electrician_profiles
   WHERE (user_id=auth.uid() OR auth_user_id=auth.uid())
     AND verification_status='approved' AND active=true
   ORDER BY created_at DESC LIMIT 1;
  IF v_profile_id IS NULL THEN RAISE EXCEPTION 'Approved active electrician required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_booking FROM public.service_bookings
   WHERE id=p_booking_id AND assigned_electrician_id=v_profile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Assigned booking not found' USING ERRCODE='42501'; END IF;
  IF p_status='inspection' AND v_booking.status='assigned' THEN
    UPDATE public.service_bookings SET status='inspection' WHERE id=p_booking_id;
  ELSE RAISE EXCEPTION 'Invalid booking status transition'; END IF;
  RETURN pg_catalog.jsonb_build_object('success',true,'status',p_status);
END;
$function$;

